package ru.artem.beforethefall.equipment;
import org.bukkit.Bukkit; import org.bukkit.ChatColor; import org.bukkit.Material; import org.bukkit.NamespacedKey; import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler; import org.bukkit.event.Listener; import org.bukkit.event.player.PlayerInteractEvent; import org.bukkit.inventory.EquipmentSlot; import org.bukkit.inventory.ItemStack; import org.bukkit.inventory.meta.ItemMeta; import org.bukkit.persistence.PersistentDataType; import org.bukkit.scheduler.BukkitTask; import ru.artem.beforethefall.BeforeTheFallPlugin; import java.util.List;
public final class GasMaskManager implements Listener {
 private final BeforeTheFallPlugin plugin; private final NamespacedKey marker,filter,filterItem; private BukkitTask task;
 public GasMaskManager(BeforeTheFallPlugin plugin){this.plugin=plugin;marker=new NamespacedKey(plugin,"gas_mask");filter=new NamespacedKey(plugin,"filter_ticks");filterItem=new NamespacedKey(plugin,"replacement_filter");}
 public ItemStack createMask(){ItemStack item=new ItemStack(Material.CARVED_PUMPKIN);ItemMeta meta=item.getItemMeta();meta.setDisplayName(ChatColor.DARK_GREEN+"Противогаз");meta.setCustomModelData(1);meta.setLore(List.of(ChatColor.GRAY+"Защищает от радиоактивной пыли и пепла",ChatColor.GRAY+"Фильтр изготавливается отдельно",ChatColor.YELLOW+"Надень в слот шлема"));meta.getPersistentDataContainer().set(marker,PersistentDataType.BYTE,(byte)1);meta.getPersistentDataContainer().set(filter,PersistentDataType.INTEGER,0);item.setItemMeta(meta);return item;}
 public ItemStack createFilter(){ItemStack item=new ItemStack(Material.IRON_INGOT);ItemMeta meta=item.getItemMeta();meta.setDisplayName(ChatColor.GREEN+"Сменный фильтр");meta.setCustomModelData(2);meta.setLore(List.of(ChatColor.GRAY+"Картридж для противогаза",ChatColor.GRAY+"Ресурс: "+plugin.getConfig().getInt("gas-mask.filter-duration-seconds",900)+" секунд"));meta.getPersistentDataContainer().set(filterItem,PersistentDataType.BYTE,(byte)1);item.setItemMeta(meta);return item;}
 public boolean isFilter(ItemStack item){if(item==null||!item.hasItemMeta())return false;Byte v=item.getItemMeta().getPersistentDataContainer().get(filterItem,PersistentDataType.BYTE);return v!=null&&v==(byte)1;}
 public boolean isMask(ItemStack item){if(item==null||!item.hasItemMeta())return false;Byte v=item.getItemMeta().getPersistentDataContainer().get(marker,PersistentDataType.BYTE);return v!=null&&v==(byte)1;}
 private int filterTicks(ItemStack item){if(!isMask(item))return 0;Integer v=item.getItemMeta().getPersistentDataContainer().get(filter,PersistentDataType.INTEGER);return v==null?0:v;}
 public int remainingSeconds(ItemStack item){return Math.max(0,filterTicks(item)/2);}
 private void setFilterTicks(ItemStack item,int ticks){ItemMeta meta=item.getItemMeta();meta.getPersistentDataContainer().set(filter,PersistentDataType.INTEGER,Math.max(0,ticks));meta.setLore(List.of(ChatColor.GRAY+"Защищает от радиоактивной пыли и пепла",ChatColor.GRAY+"Осталось: "+Math.max(0,ticks/2)+" сек.",ticks>0?ChatColor.GREEN+"Фильтр установлен":ChatColor.RED+"Фильтр пуст"));item.setItemMeta(meta);}
 public boolean isProtected(Player p){ItemStack h=p.getInventory().getHelmet();return isMask(h)&&filterTicks(h)>0;}
 @EventHandler public void onFilterUse(PlayerInteractEvent e){if(e.getHand()!=EquipmentSlot.HAND||!isFilter(e.getItem()))return;ItemStack helmet=e.getPlayer().getInventory().getHelmet();if(!isMask(helmet)){e.getPlayer().sendMessage(ChatColor.RED+"Сначала надень противогаз в слот шлема.");return;}setFilterTicks(helmet,plugin.getConfig().getInt("gas-mask.filter-duration-seconds",900)*2);ItemStack held=e.getItem();if(held!=null&&held.getAmount()>1)held.setAmount(held.getAmount()-1);else e.getPlayer().getInventory().setItemInMainHand(null);e.getPlayer().sendMessage(ChatColor.GREEN+"Фильтр заменён. Защита восстановлена на 15 минут.");e.setCancelled(true);}
 public void start(){task=Bukkit.getScheduler().runTaskTimer(plugin,()->{for(Player p:Bukkit.getOnlinePlayers()){ItemStack h=p.getInventory().getHelmet();if(!isMask(h))continue;int r=filterTicks(h);if(r<=0)continue;setFilterTicks(h,r-1);if(r==1)p.sendMessage(ChatColor.RED+"Фильтр противогаза исчерпан! Используй сменный фильтр.");}},10L,10L);}
 public void stop(){if(task!=null)task.cancel();}
}